        shared_data[i] = exp_val;
        sum_exp += exp_val;
    }
    __syncthreads();

    // Reduction to find sum
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s && tid + s < num_features) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    half global_sum = shared_data[0];

    // Normalize and write output
    for (int i = tid; i < num_features; i += stride) {
        int idx = batch_idx * num_features + i;
        output[idx] = shared_data[i] / global_sum;
    }
}

