    // Use warp-level reductions for better performance
    for (int offset = 16; offset > 0; offset /= 2) {
        max_val = fmaxf(max_val, __shfl_down_sync(0xffffffff, max_val, offset));
    }

    // Compute sum of exponentials
    half sum_exp = 0.0h;
